import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"缓冲膨胀","description":"","frontmatter":{"title":"缓冲膨胀","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bufferbloat.md","filePath":"cs/bufferbloat.md","lastUpdated":1789023840000}'),h={name:"cs/bufferbloat.md"};function f(u,a,_,E,B,b){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="缓冲膨胀" tabindex="-1">缓冲膨胀 <a class="header-anchor" href="#缓冲膨胀" aria-label="Permalink to &quot;缓冲膨胀&quot;">​</a></h1><div class="epigraph"><p>过大的瓶颈缓冲让 AIMD 在已满 $C$ 之后仍堆延迟；吞吐看起来很好，交互 RTT 变成秒级。</p><footer>—— 据 Gettys and Nichols, Bufferbloat, ACM Queue 2011；RFC 7567 整理</footer></div><p><a href="/cs/bandwidth-delay-product">BDP</a> 说缓冲约一 BDP。<a href="/cs/aqm-red-codel">AQM</a> 是药。<a href="/cs/ecn">上一课</a> 给标记。缺口是<strong>命名膨胀</strong>：家用路由、LTE 基站、Cable 调制解调器里的巨缓冲。本课不把 WFQ 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>网卡和驱动按「丢包坏」堆兆字节。TCP 填满缓冲才丢，稳态延迟 = 缓冲/\\(C\\)，可远超传播。测速工具显示线速，ssh 却卡——因为共享同一队列。卫星固有延迟不是膨胀；膨胀是可消灭的排队。FQ-CoDel 把大象流隔开，老鼠流不排队。</p><p>不要把所有高 RTT 都叫膨胀：先减传播与无线调度。</p><p><span class="marginnote">Gettys 普及该词。本课不点名某调制解调器固件。</span></p><h3 id="吞吐满而交互死" tabindex="-1">吞吐满而交互死 <a class="header-anchor" href="#吞吐满而交互死" aria-label="Permalink to &quot;吞吐满而交互死&quot;">​</a></h3><p>排队延迟 = 缓冲/\\(C\\)。灌流前后 ping 对照。卫星固有传播不是膨胀。过浅则 incast。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：浅缓冲丢包 vs 深缓冲延迟。画：cwnd 超过 BDP 的部分 = 队列。测：空闲 ping vs 灌流 ping。incast 是过浅；膨胀是过深；数据中心与接入网方向相反。</p>',11)),(e(),n(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22TCP%20%E5%A1%AB%E7%BC%93%E5%86%B2%22%5D%20--%3E%20DELAY%5B%22%E6%8E%92%E9%98%9F%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20DELAY%20--%3E%20SIG%5B%22%E5%BE%88%E6%99%9A%E6%89%8D%E4%B8%A2%2F%E6%A0%87%22%5D%0A%20%20AQM%5B%22AQM%2FFQ%22%5D%20--%3E%20SHAL%5B%22%E5%8E%8B%E5%9B%9E%E6%B5%85%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗口缩放「成功」后更容易堆满巨型缓冲。PFC 无损也会堆延迟，只是不丢。5G 切片可给 URLLC 独立浅队列，避免被 eMBB 膨胀。测量后课 iperf 要同时看 RTT。</p><p>与 HOL：膨胀是单队列深度；HOL 是结构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BQL 网卡字节队列的全部。WFQ 是下一课。后课默认：过大缓冲把延迟藏进吞吐数字；AQM 或每流排队是解。</p><p>给接入网「更大缓冲抗抖动」要有上界，否则交互死。</p><p>上一课留下的缺口在本课收口；「缓冲膨胀」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/wfq-fair-queue">WFQ</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>膨胀：队列延迟主导 RTT，吞吐仍满。</li><li>测灌流前后的 ping。</li><li>AQM/FQ 针对它；incast 是反面。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Gettys–Nichols, 2011；RFC 7567。</li></ul>',10))])}const A=o(h,[["render",f]]);export{T as __pageData,A as default};
